import React from 'react';
import ReactDOM from 'react-dom/client';
import { BrowserRouter } from 'react-router-dom';
import { HelmetProvider } from 'react-helmet-async';
import { QueryClient } from '@tanstack/react-query';
import { PersistQueryClientProvider } from '@tanstack/react-query-persist-client';
import { createAsyncStoragePersister } from '@tanstack/query-async-storage-persister';
import { get, set, del } from 'idb-keyval'; // npm install idb-keyval
// This module is generated by vite-plugin-pwa at build time and has no
// standalone TypeScript declaration in the editor.
// @ts-expect-error vite-plugin-pwa provides this virtual module at build time.
import { registerSW } from 'virtual:pwa-register';
import App from './App';
import './monitoring';
import './index.css';
import './i18n/config';
import { PwaUpdateBanner } from './components/common/PwaUpdateBanner';

// IndexedDB Persister (Çevrimdışı verileri tarayıcıda tutmak için)
const indexedDBPersister = createAsyncStoragePersister({
  storage: {
    getItem: async (key) => (await get<string>(key)) ?? null,
    setItem: async (key, value) => {
      await set(key, value);
    },
    removeItem: async (key) => {
      await del(key);
    },
  },
});

const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      staleTime: 1000 * 60 * 5,
      gcTime: 1000 * 60 * 60 * 24, // 24 saat cache'te tut
    },
    mutations: {
      // İnternet yoksa mutation'ı durdur ve IndexedDB'ye al, gelince otomatik çalıştır
      networkMode: 'offlineFirst',
    },
  },
});

const updateSW = registerSW({
  immediate: true,
  onNeedRefresh() {
    window.dispatchEvent(new CustomEvent('pwa-update-available', { detail: updateSW }));
  },
});

ReactDOM.createRoot(document.getElementById('root')!).render(
  <React.StrictMode>
    <PersistQueryClientProvider 
      client={queryClient} 
      persistOptions={{ persister: indexedDBPersister, maxAge: 1000 * 60 * 60 * 24 }}
    >
      <BrowserRouter>
        <HelmetProvider>
          <App />
          <PwaUpdateBanner />
        </HelmetProvider>
      </BrowserRouter>
    </PersistQueryClientProvider>
  </React.StrictMode>
);